import{U as e,W as t,nt as n,t as r}from"./chunks/framework.DRwsyrlO.js";var i=JSON.parse(`{"title":"出发前必读：离岛毕业规则","description":"成功离岛航行对岛主、队员、原岛建筑、随身物资和重生路线的影响，以及出发前应核对的事项。","frontmatter":{"title":"出发前必读：离岛毕业规则","description":"成功离岛航行对岛主、队员、原岛建筑、随身物资和重生路线的影响，以及出发前应核对的事项。"},"headers":[],"relativePath":"skyblock/graduation.md","filePath":"skyblock/graduation.md"}`),a={name:`skyblock/graduation.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="出发前必读-离岛毕业规则" tabindex="-1">出发前必读：离岛毕业规则 <a class="header-anchor" href="#出发前必读-离岛毕业规则" aria-label="Permalink to “出发前必读：离岛毕业规则”">​</a></h1><p>从空岛起飞，可以是另一段生活的开始。先确认会带走什么、会改变什么，再和同岛伙伴决定什么时候出发。</p><div class="danger custom-block"><p class="custom-block-title">岛主毕业会影响整座岛屿</p><p>成功的空岛 → 太阳系太空飞船迁移会触发离岛毕业。<strong>岛主毕业会注销原岛，影响队友；普通成员毕业会退出原岛屿。</strong> 这不是一次无损的临时观光传送。</p></div><h2 id="什么情况下进入毕业流程" tabindex="-1">什么情况下进入毕业流程？ <a class="header-anchor" href="#什么情况下进入毕业流程" aria-label="Permalink to “什么情况下进入毕业流程？”">​</a></h2><p>当前流程连接实际成功的飞船迁移与玩家到达目标世界，不把任意传送都当作毕业，也不应把失败的迁移算成成功离岛。</p><p>不要自行通过换维度或管理员命令试探毕业条件。出发前请确认当前服内规则，尤其是多人乘船时的身份与队伍安排。</p><h2 id="岛主、队员与乘员的区别" tabindex="-1">岛主、队员与乘员的区别 <a class="header-anchor" href="#岛主、队员与乘员的区别" aria-label="Permalink to “岛主、队员与乘员的区别”">​</a></h2><table tabindex="0"><thead><tr><th>身份</th><th>已知影响</th></tr></thead><tbody><tr><td>岛主毕业</td><td>注销原岛，影响原岛成员及其建设安排，应先与全体同岛伙伴商量</td></tr><tr><td>普通成员毕业</td><td>退出所属岛屿，不是继续保留原来的岛屿成员关系</td></tr><tr><td>同船乘员</td><td>个人资格、归属与同时到达等细则仍待服主公布最终说明，不应假定“搭船就不会毕业”或“所有乘员完全相同”</td></tr></tbody></table><p>毕业后身份与重生路线会改变。当前交接资料尚不足以公开完整乘员执行表，<strong>多人航行前需向管理员确认</strong>。</p><h2 id="哪些东西能带走" tabindex="-1">哪些东西能带走？ <a class="header-anchor" href="#哪些东西能带走" aria-label="Permalink to “哪些东西能带走？”">​</a></h2><p>当前毕业流程保留背包与末影箱。出发前仍应核对重要物资的存放位置与船体边界。</p><ul><li>原岛上的建筑、机器和箱子<strong>不会自动打包成飞船</strong>。</li><li>原岛关系注销后，不应再把旧地形当作可继续使用的资产。</li><li>即使看到旧地形残留，也不构成原岛永久保留或能够返回建设的承诺。</li><li>不保证所有模组机器、内部库存及船体组合都能无损迁移，重要组合需先确认兼容性。</li></ul><h2 id="checklist" tabindex="-1">出发前检查 <a class="header-anchor" href="#checklist" aria-label="Permalink to “出发前检查”">​</a></h2><ol><li><strong>与伙伴达成一致</strong>：确认谁是岛主，毕业会影响哪些成员和共同作品。</li><li><strong>核对乘员规则</strong>：确认每位乘员的任务资格、岛屿归属与到达后的安排。</li><li><strong>整理随身物资</strong>：将要保留的物资安排到已确认可保留的位置，不把原岛库存当成会自动带走。</li><li><strong>确认船体与燃料</strong>：检查研究、组装、设备及航行条件，核对随船机器兼容性。</li><li><strong>确认重生路线</strong>：合法船锚、绑定与维度条件需要满足，不默认死亡后会回到船上。</li><li><strong>了解目的地环境</strong>：提前准备环境装备，确认可登陆性与后续补给。</li></ol><div class="warning custom-block"><p class="custom-block-title">最终细则仍需核对</p><p>乘员处理、原岛地形清理与重生安排仍需服主提供最终规则。涉及多人或重要资产的出发，应先完成这一步确认。本页是现有机制的风险说明，不代表已完成所有客户端组合的航行验收。</p></div><p><a href="./spaceflight.html">航天资格与飞船准备</a> · <a href="./stations.html">空间站生活</a> · <a href="./">返回科技空岛</a></p><p>资料整理：2026-11-20。</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};